contracts/LoveLedger.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title LoveLedger
 * @dev Single source of truth for P31 Ontological Volume.
 * Issues soulbound (non-transferable) L.O.V.E. based on 501(c)(3) donations.
 */
contract LoveLedger {
    address public immutable operator;

    // Cryptographic ledger of Ontological Volume
    mapping(address => uint256) public vestedVolume;

    event VolumeInjected(address indexed donor, uint256 volumeAdded, uint256 totalVolume);

    constructor() {
        operator = msg.sender;
    }

    /**
     * @dev Injects volume into the network. ETH is held in treasury, volume is permanently vested.
     * @param usdVolume The computed USD equivalent being injected.
     */
    function injectVolume(uint256 usdVolume) external payable {
        require(msg.value > 0, "Zero volume injection");

        vestedVolume[msg.sender] += usdVolume;

        emit VolumeInjected(msg.sender, usdVolume, vestedVolume[msg.sender]);
    }

    /**
     * @dev Routes accumulated ETH to the secure P31 501(c)(3) hardware treasury.
     */
    function routeToTreasury(address payable treasury) external {
        require(msg.sender == operator, "Operator only");
        treasury.transfer(address(this).balance);
    }
}

